<?php
require_once __DIR__ . '/includes/bootstrap.php';
$page_title='Cari laptop sesuai kebutuhan'; $active_page='recommend';
$budget = filter_input(INPUT_GET, 'budget', FILTER_VALIDATE_INT) ?: 8000000;
$purpose = (string)($_GET['purpose'] ?? 'Kuliah'); $condition = (string)($_GET['condition'] ?? ''); $category = (string)($_GET['category'] ?? '');
$purposes = ['Kuliah','Produktivitas','Desain','Gaming','Teknik','Multimedia'];
$validPurpose = in_array($purpose,$purposes,true) ? $purpose : 'Kuliah';
$products = [];
if (isset($_GET['find'])) {
  $where=['is_published=1','price <= :budget']; $params=['budget'=>max(0,$budget)];
  if(in_array($condition,['Baru','Bekas'],true)){ $where[]='condition_type=:cond'; $params['cond']=$condition; }
  if(in_array($category,['Global','ODM'],true)){ $where[]='category_type=:cat'; $params['cat']=$category; }
  $where[]='use_cases LIKE :purpose'; $params['purpose']='%'.$validPurpose.'%';
  $sql="SELECT * FROM laptops WHERE ".implode(' AND ',$where)." ORDER BY FIELD(tier,'S+','S','A+','A','B+','B','C'), price ASC LIMIT 30";
  $st=db()->prepare($sql);$st->execute($params);$products=$st->fetchAll();
}
require __DIR__.'/includes/header.php';
?>
